class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        mod = 10**9 + 7
        m = target // 2
        if n <= m:
            return (n * (n + 1) // 2) % mod
        ans = m * (m + 1) // 2
        rem = n - m
        ans += (target + target + rem - 1) * rem // 2
        return ans % mod

class Solution {
public:
    int minimumPossibleSum(int n, int target) {
        long long mod = 1e9 + 7;
        long long m = target / 2;
        if (n <= m) {
            return (1LL * n * (n + 1) / 2) % mod;
        }
        long long ans = (m * (m + 1) / 2) % mod;
        long long rem = n - m;
        long long second_sum = ((target + target + rem - 1) % mod * (rem % mod) / 2) % mod;
        return (ans + second_sum) % mod;
    }
};

class Solution {
    public int minimumPossibleSum(int n, int target) {
        long mod = 1_000_000_007L;
        long m = target / 2;
        if (n <= m) {
            return (int) ((1L * n * (n + 1) / 2) % mod);
        }
        long ans = m * (m + 1) / 2;
        long rem = n - m;
        ans += (2L * target + rem - 1) * rem / 2;
        return (int) (ans % mod);
    }
}

/**
 * @param {number} n
 * @param {number} target
 * @return {number}
 */
var minimumPossibleSum = function(n, target) {
    const mod = 1000000007n;
    const bn = BigInt(n);
    const bTarget = BigInt(target);
    const m = bTarget / 2n;
    if (bn <= m) {
        return Number((bn * (bn + 1n) / 2n) % mod);
    }
    const ans1 = m * (m + 1n) / 2n;
    const rem = bn - m;
    const ans2 = (bTarget + bTarget + rem - 1n) * rem / 2n;
    return Number((ans1 + ans2) % mod);
};
